update known_safe_harbors set tissue_context = 'Primary human T cells' where source_pmid = '41121349' and evidence_summary = 'Cytogenetic band 14q11.2. CRISPR/Cas9-mediated integration in primary human T cells -- "robust and consistent" CAR expression driven by the endogenous TRAC promoter. Dual benefit: the insertion disrupts the endogenous TCR, reducing graft-versus-host disease (GVHD) risk in allogeneic products. Sits in a transcriptionally active genomic environment, with no nearby oncogenic elements. Via secondary review, not verified against the primary article.';
