update known_safe_harbors set tissue_context = 'CAR-CD19 T cells (murine leukemia model, exact cell source not itemized)' where source_pmid = '41121349' and evidence_summary = 'Chromosome not specified in the review. Anti-CD19 CAR T cells integrated at this locus showed potent antitumor activity in murine models of B-cell acute lymphoblastic leukemia, with efficacy comparable to the TRAC locus. Described as meeting all 8 GSH design criteria (including ncRNA protection and chromatin accessibility). Low confidence due to lack of a specific genomic location. Via secondary review, not verified against the primary article.';
update public_safe_harbors_staging set tissue_context = 'CAR-CD19 T cells (murine leukemia model, exact cell source not itemized)' where source_pmid = '41121349' and evidence_summary = 'Chromosome not specified in the review. Anti-CD19 CAR T cells integrated at this locus showed potent antitumor activity in murine models of B-cell acute lymphoblastic leukemia, with efficacy comparable to the TRAC locus. Described as meeting all 8 GSH design criteria (including ncRNA protection and chromatin accessibility). Low confidence due to lack of a specific genomic location. Via secondary review, not verified against the primary article.';

update known_safe_harbors set tissue_context = 'Mouse macrophages (RAW 264.7); also cerebellum/limb tissue in TRE-loxP intersectional lines' where source_pmid = '38841290' and evidence_summary = 'The Tigre locus (Igs7) used as a safe harbor in mouse macrophages (RAW 264.7) alongside ROSA26 for endogenous fluorescent knock-ins, and in mouse lines with a TRE-loxP system for intersectional expression in cerebellum and limbs. Established as an alternative to ROSA26, not merely theoretical.';
