update known_safe_harbors set tissue_context = 'Mouse oocytes (Gdf9-driven, oocyte-specific Cas9 line)' where source_pmid = '38523431' and evidence_summary = 'The Hprt1 locus (X-linked) used for single-copy integration of a Cas9 transgene (Gdf9-Cas9) -- chosen precisely because it is a well-defined integration site that "does not influence transgene expression". Genome editing mediated by the transgenic Cas9 was as efficient as exogenous Cas9.';
update public_safe_harbors_staging set tissue_context = 'Mouse oocytes (Gdf9-driven, oocyte-specific Cas9 line)' where source_pmid = '38523431' and evidence_summary = 'The Hprt1 locus (X-linked) used for single-copy integration of a Cas9 transgene (Gdf9-Cas9) -- chosen precisely because it is a well-defined integration site that "does not influence transgene expression". Genome editing mediated by the transgenic Cas9 was as efficient as exogenous Cas9.';

update known_safe_harbors set tissue_context = 'Human HAP1 cells' where source_pmid = '34805274' and evidence_summary = 'In human HAP1 cells, expression of auxin-binding F-box receptor proteins (AFB) from a transgene tends to decline with passaging in the absence of constant antibiotic selection -- does not prevent epigenetic silencing of the transgene even at the AAVS1 locus.';
