update known_safe_harbors set tissue_context = 'hiPSCs, differentiated into cardiomyocytes and endothelium' where source_pmid = '38372898' and evidence_summary = 'Important finding: dCas9-VPR (CRISPRa) targeted to AAVS1 in hiPSCs activates target genes well during pluripotency, but silences after differentiation into cardiomyocytes and endothelium -- in direct CONTRAST with simple fluorescent proteins in the same construct/locus, which remain expressed. Silencing is payload-dependent, not just locus-dependent.';
update public_safe_harbors_staging set tissue_context = 'hiPSCs, differentiated into cardiomyocytes and endothelium' where source_pmid = '38372898' and evidence_summary = 'Important finding: dCas9-VPR (CRISPRa) targeted to AAVS1 in hiPSCs activates target genes well during pluripotency, but silences after differentiation into cardiomyocytes and endothelium -- in direct CONTRAST with simple fluorescent proteins in the same construct/locus, which remain expressed. Silencing is payload-dependent, not just locus-dependent.';

update known_safe_harbors set tissue_context = 'hiPSCs, differentiated into cardiomyocytes and endothelium' where source_pmid = '38372898' and evidence_summary = 'Same comparative study: dCas9-VPR targeted to hROSA26 also silences after differentiation into cardiomyocytes/endothelium, despite working well during pluripotency -- same pattern as AAVS1 and CLYBL in the same study. Reinforces that the payload (dCas9-VPR vs. a fluorescent reporter) is the determining factor for silencing, not the chosen locus.';
update public_safe_harbors_staging set tissue_context = 'hiPSCs, differentiated into cardiomyocytes and endothelium' where source_pmid = '38372898' and evidence_summary = 'Same comparative study: dCas9-VPR targeted to hROSA26 also silences after differentiation into cardiomyocytes/endothelium, despite working well during pluripotency -- same pattern as AAVS1 and CLYBL in the same study. Reinforces that the payload (dCas9-VPR vs. a fluorescent reporter) is the determining factor for silencing, not the chosen locus.';

update known_safe_harbors set tissue_context = 'hiPSCs, differentiated into cardiomyocytes and endothelium' where source_pmid = '38372898' and evidence_summary = 'Same comparative study: dCas9-VPR targeted to CLYBL also silences after differentiation into cardiomyocytes/endothelium, even though CLYBL is generally considered the best-performing locus among the three tested in this article. Reinforces that payload (not locus) determines silencing in this case.';
update public_safe_harbors_staging set tissue_context = 'hiPSCs, differentiated into cardiomyocytes and endothelium' where source_pmid = '38372898' and evidence_summary = 'Same comparative study: dCas9-VPR targeted to CLYBL also silences after differentiation into cardiomyocytes/endothelium, even though CLYBL is generally considered the best-performing locus among the three tested in this article. Reinforces that payload (not locus) determines silencing in this case.';

update known_safe_harbors set tissue_context = 'Patient-derived iPSCs and differentiated endothelial cells; in vivo blood/subcutaneous transplant in mice' where source_pmid = '39762408' and evidence_summary = 'FE-FVIII variant (hemophilia A) inserted at AAVS1 via Cas9(D10A) nickase in patient-derived iPSCs. Expressed in undifferentiated iPSCs AND in differentiated endothelial cells. HA mice transplanted with these ECs: 2.12x increase in blood FVIII activity, ~20% higher post-hemorrhage survival, effect maintained >3 months after subcutaneous transplant.';
update public_safe_harbors_staging set tissue_context = 'Patient-derived iPSCs and differentiated endothelial cells; in vivo blood/subcutaneous transplant in mice' where source_pmid = '39762408' and evidence_summary = 'FE-FVIII variant (hemophilia A) inserted at AAVS1 via Cas9(D10A) nickase in patient-derived iPSCs. Expressed in undifferentiated iPSCs AND in differentiated endothelial cells. HA mice transplanted with these ECs: 2.12x increase in blood FVIII activity, ~20% higher post-hemorrhage survival, effect maintained >3 months after subcutaneous transplant.';

update known_safe_harbors set tissue_context = 'hPSCs differentiated into forebrain organoids' where source_pmid = '39545087' and evidence_summary = 'ChR2 (channelrhodopsin-2) inserted at AAVS1 in hPSCs, differentiated into forebrain organoids. Homogeneous, stable expression throughout the region, without structural/functional disruption, robust and consistent light-driven neuronal activation. Directly relevant to neuronal contexts.';
update public_safe_harbors_staging set tissue_context = 'hPSCs differentiated into forebrain organoids' where source_pmid = '39545087' and evidence_summary = 'ChR2 (channelrhodopsin-2) inserted at AAVS1 in hPSCs, differentiated into forebrain organoids. Homogeneous, stable expression throughout the region, without structural/functional disruption, robust and consistent light-driven neuronal activation. Directly relevant to neuronal contexts.';

update known_safe_harbors set tissue_context = 'Jurkat T cells' where source_pmid = '35795775' and evidence_summary = 'In Jurkat T cells, a transgene at AAVS1 does not silence up to 160 days -- but expression shows huge transcriptional variation, over two orders of magnitude (100x) between cells, measured by barcoding + single-cell next-generation sequencing. Does not silence, but is highly heterogeneous in magnitude.';
update public_safe_harbors_staging set tissue_context = 'Jurkat T cells' where source_pmid = '35795775' and evidence_summary = 'In Jurkat T cells, a transgene at AAVS1 does not silence up to 160 days -- but expression shows huge transcriptional variation, over two orders of magnitude (100x) between cells, measured by barcoding + single-cell next-generation sequencing. Does not silence, but is highly heterogeneous in magnitude.';

update known_safe_harbors set tissue_context = 'iPSCs differentiated into myeloid cells (neutrophil/macrophage lineage)' where source_pmid = '31773990' and evidence_summary = 'Correction of p47phox deficiency (chronic granulomatous disease) via AAVS1 in iPSCs, testing 3 myeloid-specific promoters after differentiation: miR223 and CatG/cFes gave therapeutically relevant expression; the MRP8 promoter was much less efficient due to high CpG methylation in differentiated cells. Silencing depends strongly on the chosen promoter, not just the locus.';
update public_safe_harbors_staging set tissue_context = 'iPSCs differentiated into myeloid cells (neutrophil/macrophage lineage)' where source_pmid = '31773990' and evidence_summary = 'Correction of p47phox deficiency (chronic granulomatous disease) via AAVS1 in iPSCs, testing 3 myeloid-specific promoters after differentiation: miR223 and CatG/cFes gave therapeutically relevant expression; the MRP8 promoter was much less efficient due to high CpG methylation in differentiated cells. Silencing depends strongly on the chosen promoter, not just the locus.';

update known_safe_harbors set tissue_context = 'hiPSCs, differentiated into cardiomyocytes' where source_pmid = '32789000' and evidence_summary = 'Title of the article itself: identifies AAVS1 as "not an entirely safe harbour". Of 24 targeted hiPSC clones, only 20 expressed the transgene, ranging 0-99.5% positive cells. During differentiation into cardiomyocytes, silencing was observed: 98.93% -> 1.3% positive cells in one clone. A doxycycline-inducible system showed up to a 10,000x drop within 8-10 days. Expression only rescued with continuous puromycin selection.';
update public_safe_harbors_staging set tissue_context = 'hiPSCs, differentiated into cardiomyocytes' where source_pmid = '32789000' and evidence_summary = 'Title of the article itself: identifies AAVS1 as "not an entirely safe harbour". Of 24 targeted hiPSC clones, only 20 expressed the transgene, ranging 0-99.5% positive cells. During differentiation into cardiomyocytes, silencing was observed: 98.93% -> 1.3% positive cells in one clone. A doxycycline-inducible system showed up to a 10,000x drop within 8-10 days. Expression only rescued with continuous puromycin selection.';

update known_safe_harbors set tissue_context = 'Peripheral blood cells in vivo (mouse), following HSC transduction' where source_pmid = '31494053' and evidence_summary = 'Transgenic mice carrying the human AAVS1 target sequence, tested with in vivo hematopoietic stem cell (HSC) transduction using HDAd5/35++ vectors. On average >60% of peripheral blood cells expressed the transgene after in vivo selection -- gamma-globin expression significantly higher and more stable than with random integration (SB100x-transposase system) used as a comparator in the same study.';
