update known_safe_harbors set tissue_context = 'Liver-exclusive in vivo expression (mouse), confirmed from embryonic stage E16.5' where source_pmid = '30591434' and evidence_summary = 'H11-albumin-rtTA mice (albumin promoter driving rtTA at the H11 locus) -- liver-exclusive, doxycycline-inducible expression, confirmed by crossing with a TetO-H2BGFP reporter. Cre-mediated recombination as efficient as the conventional Albumin-Cre control. Reporter expression detectable already from embryonic stage E16.5 when induced.';
