update known_safe_harbors set tissue_context = 'Human iPSCs, long-term culture and multi-lineage differentiation' where source_pmid = '26707206' and evidence_summary = 'Robust, reproducible CAG-promoter-driven expression at AAVS1 (PPP1R12C intron), with reproducible copy-number control between subclones (~2x). Expression maintained during long-term culture of human iPSCs and through differentiation into multiple lineages. Widely used protocol/methodology paper, commonly cited as a reference.';
