update known_safe_harbors set tissue_context = 'Undifferentiated hESCs and differentiated hepatocytes' where source_pmid = '26455413' and evidence_summary = 'Explicit conclusion from the title itself: "AAVS1 Locus-Mediated Transgene Inhibition". Unexpected, variable expression inhibition observed both in undifferentiated hESCs and in differentiated hepatocytes, attributed to DNA methylation and other unknown mechanisms. Authors'' conclusion: "AAVS1 cannot be considered a universally safe harbor for reliable transgene expression in vitro".';
