update known_safe_harbors set tissue_context = 'Mouse ES cells' where source_pmid = '19279185' and evidence_summary = 'Promoter comparison within the ROSA26 locus itself in mouse ES cells: direct expression from the endogenous ROSA26 promoter gives a moderate level; inserting a CAGG promoter at the ROSA26 locus gives higher expression. Expression level at ROSA26 depends strongly on the promoter used, not just the choice of locus.';
