update known_safe_harbors set tissue_context = 'hESC-derived lineages (multiple, not itemized)' where source_pmid = '18037879' and evidence_summary = 'Founding paper identifying the human homolog of the mouse ROSA26 locus. tdRFP targeted by homologous recombination was expressed across multiple hESC-derived lineages. Recombinase-mediated cassette exchange (RMCE) demonstrated to swap the transgene for other cDNAs at the same locus.';
