update known_safe_harbors set tissue_context = 'Human embryonic stem cells (hESCs), including 15-day differentiation' where source_pmid = '18024421' and evidence_summary = 'Founding paper (2007), direct quantified comparison with random integration: with selection, 90+-4% positive cells at AAVS1 vs. 57+-32% with random integration; 25 days after removing selection, 86+-7% vs. only 39+-31% (random) -- i.e. much more resistant to silencing. After 15 days of differentiation, >90% (AAVS1) vs. ~30% (random) still positive. One of the most cited papers in the field.';
update public_safe_harbors_staging set tissue_context = 'Human embryonic stem cells (hESCs), including 15-day differentiation' where source_pmid = '18024421' and evidence_summary = 'Founding paper (2007), direct quantified comparison with random integration: with selection, 90+-4% positive cells at AAVS1 vs. 57+-32% with random integration; 25 days after removing selection, 86+-7% vs. only 39+-31% (random) -- i.e. much more resistant to silencing. After 15 days of differentiation, >90% (AAVS1) vs. ~30% (random) still positive. One of the most cited papers in the field.';

update known_safe_harbors set tissue_context = 'CAR-CD19 T cells (murine leukemia model)' where source_pmid = '36745870' and evidence_summary = 'Extragenic locus identified by a proprietary algorithm (7 criteria to minimize genotoxicity and maximize CRISPR/Cas9 efficiency and resistance to silencing). CAR-CD19 T cells built at GSH6 were curative at a low cell dose in a murine acute lymphoblastic leukemia model, matching the potency of CAR-T cells built at the TRAC locus, and resisting tumor rechallenge 100 days after infusion. Substantially stronger data than the brief mention found earlier via secondary review -- this is the primary paper.';
update public_safe_harbors_staging set tissue_context = 'CAR-CD19 T cells (murine leukemia model)' where source_pmid = '36745870' and evidence_summary = 'Extragenic locus identified by a proprietary algorithm (7 criteria to minimize genotoxicity and maximize CRISPR/Cas9 efficiency and resistance to silencing). CAR-CD19 T cells built at GSH6 were curative at a low cell dose in a murine acute lymphoblastic leukemia model, matching the potency of CAR-T cells built at the TRAC locus, and resisting tumor rechallenge 100 days after infusion. Substantially stronger data than the brief mention found earlier via secondary review -- this is the primary paper.';

update known_safe_harbors set tissue_context = 'Human rhabdomyosarcoma cells' where source_pmid = '30793977' and evidence_summary = 'Additional detail on a locus already registered: transgene-encoded Cas9 proteins at SHS231 (chromosome 4) used to introduce a large (17kb) gRNA-guided deletion in the PAX3/FOXO1 fusion oncogene in human rhabdomyosarcoma cells, and as a Cas9-VPR fusion to activate the muscle transcription factor MYF5. Confirms transgene function, not just expression, at this locus.';
update public_safe_harbors_staging set tissue_context = 'Human rhabdomyosarcoma cells' where source_pmid = '30793977' and evidence_summary = 'Additional detail on a locus already registered: transgene-encoded Cas9 proteins at SHS231 (chromosome 4) used to introduce a large (17kb) gRNA-guided deletion in the PAX3/FOXO1 fusion oncogene in human rhabdomyosarcoma cells, and as a Cas9-VPR fusion to activate the muscle transcription factor MYF5. Confirms transgene function, not just expression, at this locus.';

update known_safe_harbors set tissue_context = 'Human fibroblasts' where source_pmid = '26260320' and evidence_summary = 'An under-discussed safety consideration: the AAVS1 locus includes the coding region of the MBS85 gene (myosin binding subunit 85). Transgene insertion at AAVS1 significantly reduces MBS85 expression and alters myosin-II-dependent contractile force in human fibroblasts (via phosphorylation of the myosin regulatory light chain) -- effect reversed by restoring MBS85 expression. A real effect on a neighboring gene, not just a theoretical one.';
update public_safe_harbors_staging set tissue_context = 'Human fibroblasts' where source_pmid = '26260320' and evidence_summary = 'An under-discussed safety consideration: the AAVS1 locus includes the coding region of the MBS85 gene (myosin binding subunit 85). Transgene insertion at AAVS1 significantly reduces MBS85 expression and alters myosin-II-dependent contractile force in human fibroblasts (via phosphorylation of the myosin regulatory light chain) -- effect reversed by restoring MBS85 expression. A real effect on a neighboring gene, not just a theoretical one.';

